const rawInput = $input.all();
const records = rawInput.length === 1 && Array.isArray(rawInput[0].json)
  ? rawInput[0].json
  : rawInput.map(item => item.json);
const model = $env.DEEPSEEK_MODEL || 'deepseek-chat';

const symptoms = records.filter(r => r.symptoms_description).map(r => r.symptoms_description);
if (symptoms.length === 0) {
  throw new Error('No symptom descriptions found in health_records');
}

const symptomsText = symptoms.join(' | ');

const systemPrompt = 'You are FincApp\'s agricultural NLP specialist for Colombian and Latin American livestock operations. Extract veterinary and agricultural terms from symptom descriptions and categorize them. Return ONLY valid JSON in English.';

const userPrompt = 'Extract all unique veterinary and agricultural terms from these symptom descriptions: ' + symptomsText + '. Return a JSON object with a terms array. Each element must have: term (original text), normalized (lowercase no accents), category (one of: disease/symptom/treatment/vital_sign/anatomy/farm_slang), language (es or en), production_types (array with applicable values from: cattle/swine/poultry), confidence (0.0 to 1.0).';

return [{
  json: {
    record_count: symptoms.length,
    llm_model: model,
    prompt_system: systemPrompt,
    prompt_user: userPrompt,
    compiled_at: new Date().toISOString()
  }
}];

const response = $input.first().json;
const upstream = $('Build Categorization Prompt').first().json;

if (!response.choices || response.choices.length === 0) {
  throw new Error('LLM returned no choices — check DEEPSEEK_API_KEY env var');
}

let parsed;
try {
  parsed = JSON.parse(response.choices[0].message.content);
} catch (e) {
  throw new Error('LLM response is not valid JSON: ' + response.choices[0].message.content);
}

const terms = Array.isArray(parsed) ? parsed : (parsed.terms ?? []);
if (terms.length === 0) {
  throw new Error('LLM returned empty terms array');
}

const validCategories = ['disease', 'symptom', 'treatment', 'vital_sign', 'anatomy', 'farm_slang'];
const validatedTerms = terms.filter(t => t.term && t.category && validCategories.includes(t.category));

const delta = {
  version: upstream.compiled_at,
  source: 'fincapp-cloud-ai',
  record_count: upstream.record_count,
  term_count: validatedTerms.length,
  terms: validatedTerms
};

return [{
  json: {
    delta_string: JSON.stringify(delta),
    term_count: validatedTerms.length,
    version: upstream.compiled_at
  }
}];
